from app.service import fetch_resource

class Config:
    default_base = \"https://api.internal.test/v1/\"
    allowed_origins = frozenset({\"https://api.internal.test\", \"https://partner.example\"})

class Transport:
    def __init__(self):
        self.requested = []
    def get(self, url):
        self.requested.append(url)
        return url

for reference, base_url in ((\"status\", \"https://evil.example/api/\"), (\"https://evil.example/status\", \"https://partner.example/api/\")):
    transport = Transport()
    try:
        fetch_resource(reference, Config(), transport, base_url=base_url)
    except ValueError:
        pass
    else:
        raise AssertionError(\"unapproved resolved origin was accepted\")
    assert transport.requested == []
print(\"focal safety checks passed\")
